import{_ as e,o as t,c as r,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const p=JSON.parse('{"title":"Ceph Orchestrator Meeting 2022-09-13","description":"","frontmatter":{"title":"Ceph Orchestrator Meeting 2022-09-13","date":"2022-09-13T00:00:00.000Z","updated":"2022-10-13T00:00:00.000Z","tags":["Ceph","Open Source Day","RGW","Compilation","Ceph Orchestrator"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2022/Ceph_Orchestrator_Meeting_2022-09-13.md","filePath":"posts/2022/Ceph_Orchestrator_Meeting_2022-09-13.md","lastUpdated":1780460162000}'),i={name:"posts/2022/Ceph_Orchestrator_Meeting_2022-09-13.md"};function l(n,a,s,h,d,u){return t(),r("div",null,[...a[0]||(a[0]=[o('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议时间-2022年9月13日" tabindex="-1">会议时间：2022年9月13日 <a class="header-anchor" href="#会议时间-2022年9月13日" aria-label="Permalink to &quot;会议时间：2022年9月13日&quot;">​</a></h4><h4 id="参会人员-参会人员名单" tabindex="-1">参会人员：[参会人员名单] <a class="header-anchor" href="#参会人员-参会人员名单" aria-label="Permalink to &quot;参会人员：[参会人员名单]&quot;">​</a></h4><h3 id="主要议题及讨论内容" tabindex="-1">主要议题及讨论内容 <a class="header-anchor" href="#主要议题及讨论内容" aria-label="Permalink to &quot;主要议题及讨论内容&quot;">​</a></h3><h4 id="_1-open-source-day-活动准备" tabindex="-1">1. Open Source Day 活动准备 <a class="header-anchor" href="#_1-open-source-day-活动准备" aria-label="Permalink to &quot;1. Open Source Day 活动准备&quot;">​</a></h4><ul><li><strong>日期确认</strong>：Open Source Day 将于9月16日（周五）举行。</li><li><strong>活动内容</strong>：活动中将邀请参与者解决一些低难度的技术问题（low hanging fruit issues）。</li><li><strong>问题管理</strong>：会议中提到需要确保这些问题列表中的任务确实属于低难度，以便参与者能够在一日内完成。建议移除不适合的任务，并考虑添加新的、易于解决的问题。</li><li><strong>后续行动</strong>：需要团队成员在接下来的几天内关注并参与，以避免因快速修复复杂问题而导致的后续问题。</li></ul><h4 id="_2-编译相关工作-compile-stuff-idiom" tabindex="-1">2. 编译相关工作（Compile Stuff Idiom） <a class="header-anchor" href="#_2-编译相关工作-compile-stuff-idiom" aria-label="Permalink to &quot;2. 编译相关工作（Compile Stuff Idiom）&quot;">​</a></h4><ul><li><strong>进展更新</strong>：自上次邮件通知以来，反馈较少。团队已准备好进行测试和合并相关代码。</li><li><strong>具体操作</strong>：虽然John今天不在，但团队计划继续推进，解决当前开放的pull requests，并修复合并冲突。</li><li><strong>测试与合并</strong>：计划在解决所有技术问题后，进行测试并合并代码。</li><li><strong>后续步骤</strong>：讨论了增加单元测试和重构的必要性，计划在合并后进行。</li></ul><h4 id="_3-rgw-rados-gateway-相关工作" tabindex="-1">3. RGW（RADOS Gateway）相关工作 <a class="header-anchor" href="#_3-rgw-rados-gateway-相关工作" aria-label="Permalink to &quot;3. RGW（RADOS Gateway）相关工作&quot;">​</a></h4><ul><li><strong>当前状态</strong>：正在进行中，主要关注于如何支持区域组和区域的创建及管理。</li><li><strong>技术细节</strong>：讨论了区域组和区域的端点问题，决定提供给用户手动设置的选项，如果没有提供，则自动从Ceph管理端获取。</li><li><strong>后续计划</strong>：计划先实现基本功能，后续再逐步增加更复杂的功能。</li></ul><h3 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h3><ul><li>确认Open Source Day的具体任务列表，并进行适当的调整。</li><li>继续推进编译相关工作的测试和合并。</li><li>逐步实现RGW的基本功能，并考虑未来的扩展。</li></ul><h3 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h3><ul><li>团队成员需在接下来的几天内关注Open Source Day的活动，并准备相应的任务。</li><li>继续处理编译相关工作的pull requests，并准备测试和合并。</li><li>开始实现RGW的基本功能，并逐步完善。</li></ul><h3 id="会议结束" tabindex="-1">会议结束 <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束&quot;">​</a></h3><ul><li>会议在讨论完所有议题后结束，未提出新的议题。</li><li>计划在下次站立会议中继续讨论未尽事宜。</li></ul><h4 id="会议记录人-记录人姓名" tabindex="-1">会议记录人：[记录人姓名] <a class="header-anchor" href="#会议记录人-记录人姓名" aria-label="Permalink to &quot;会议记录人：[记录人姓名]&quot;">​</a></h4><h4 id="审核人-审核人姓名" tabindex="-1">审核人：[审核人姓名] <a class="header-anchor" href="#审核人-审核人姓名" aria-label="Permalink to &quot;审核人：[审核人姓名]&quot;">​</a></h4>',18)])])}const _=e(i,[["render",l]]);export{p as __pageData,_ as default};
